const APP_VERSION="11";
const PLIN_QR_DATA="data:image/png;base64,";
async function checkForUpdate(){try{const r=await fetch("version.json?t="+Date.now(),{cache:"no-store"});if(!r.ok)return;const data=await r.json();if(data.version&&String(data.version)!==APP_VERSION){location.replace(location.pathname+"?v="+encodeURIComponent(data.version))}}catch(e){}}
setInterval(checkForUpdate,30000);window.addEventListener("focus",checkForUpdate);document.addEventListener("visibilitychange",()=>{if(!document.hidden)checkForUpdate()});
const KEY="grafitex_contracts_v1";
const defaultConditions="Adelanto 50%\nCancelación del saldo contra entrega o confirmación de envío\nSe empieza el diseño una vez confirmado el depósito\nFecha de entrega: 07 días hábiles después de aprobado el diseño.";
const $=id=>document.getElementById(id), money=n=>new Intl.NumberFormat("es-PE",{style:"currency",currency:"PEN"}).format(Number(n||0));
const today=()=>new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,10);
let current=null,items=[];
const getAll=()=>{try{return JSON.parse(localStorage.getItem(KEY)||"[]")}catch{return[]}},setAll=v=>localStorage.setItem(KEY,JSON.stringify(v));
function fresh(){current=null;items=[{quantity:"",unit:"Millares",description:"",unitPrice:""}];$("contractNumber").value=String(Date.now()).slice(-7);$("contractDate").value=today();["contactName","company","taxId","phone","deposit"].forEach(id=>$(id).value="");$("showConditions").checked=false;$("conditions").value=defaultConditions;$("conditionsWrap").classList.add("hidden");$("saveBtn").textContent="Guardar contrato";$("notice").innerHTML="";renderItems();calc();window.scrollTo(0,0)}
function renderItems(){$("items").innerHTML=items.map((it,i)=>`<article class="item"><div class="itemHead"><b>Producto ${i+1}</b>${items.length>1?`<button data-remove="${i}">Quitar</button>`:""}</div><label>Descripción<textarea data-i="${i}" data-f="description" rows="2" placeholder="Ej.: Cajas en Foldcote C14, full color">${it.description||""}</textarea></label><div class="itemGrid"><label>Cantidad<input data-i="${i}" data-f="quantity" inputmode="decimal" value="${it.quantity}"></label><label>Unidad<select data-i="${i}" data-f="unit">${["Unidad","Unidades","Millar","Millares","Ciento","Servicio"].map(x=>`<option ${x===it.unit?"selected":""}>${x}</option>`).join("")}</select></label><label>Precio unitario<input data-i="${i}" data-f="unitPrice" inputmode="decimal" value="${it.unitPrice}"></label><div class="subtotal"><small>Subtotal</small><b>${money(Number(it.quantity)*Number(it.unitPrice))}</b></div></div></article>`).join("");}
function calc(){const total=items.reduce((s,x)=>s+Number(x.quantity||0)*Number(x.unitPrice||0),0),bal=total-Number($("deposit").value||0);$("total").textContent=money(total);$("balance").textContent=money(bal);$("numberBadge").textContent=$("contractNumber").value;return{total,balance:bal}}
function data(){const c=calc();return{id:current?.id||Date.now(),contractNumber:$("contractNumber").value.trim(),contractDate:$("contractDate").value,contactName:$("contactName").value.trim(),company:$("company").value.trim(),taxId:$("taxId").value.trim(),phone:$("phone").value.trim(),items:items.filter(x=>x.description.trim()),deposit:Number($("deposit").value||0),showConditions:$("showConditions").checked,conditions:$("conditions").value.trim(),total:c.total,balance:c.balance,updatedAt:new Date().toISOString()}}
function save(){const c=data();if(!c.contractNumber||!c.contractDate||(!c.contactName&&!c.company)){notice("Complete el número, la fecha y el cliente o empresa.",true);return}let all=getAll(),ix=all.findIndex(x=>x.id===c.id);if(ix>=0)all[ix]=c;else all.unshift(c);setAll(all);current=c;$("saveBtn").textContent="Actualizar contrato";notice("Contrato guardado correctamente.");renderHistory()}
function notice(t,error=false){$("notice").innerHTML=`<div class="notice ${error?"error":""}">${t}</div>`}
function openContract(c){current=c;["contractNumber","contractDate","contactName","company","taxId","phone","deposit","conditions"].forEach(id=>$(id).value=c[id]??"");$("showConditions").checked=!!c.showConditions;$("conditionsWrap").classList.toggle("hidden",!c.showConditions);items=c.items?.length?structuredClone(c.items):[{quantity:"",unit:"Millares",description:"",unitPrice:""}];$("saveBtn").textContent="Actualizar contrato";renderItems();calc();switchTab("form");window.scrollTo(0,0)}
function renderHistory(){const q=$("search").value.toLowerCase(),all=getAll();$("count").textContent=all.length;const list=all.filter(c=>[c.contractNumber,c.contactName,c.company,c.taxId,c.phone].join(" ").toLowerCase().includes(q));$("history").innerHTML=list.length?list.map(c=>`<button class="historyCard" data-open="${c.id}"><div><small>N.° ${c.contractNumber}</small><b>${c.company||c.contactName||"Cliente sin nombre"}</b><span>${c.taxId?`RUC/DNI ${c.taxId} · `:""}${new Date(c.contractDate+"T12:00:00").toLocaleDateString("es-PE")}</span></div><div><b>${money(c.total)}</b><span>Ver ›</span></div></button>`).join(""):`<div class="empty"><b>No se encontraron contratos</b><p>Pruebe con otro nombre, RUC o número.</p></div>`}
function switchTab(t){document.querySelectorAll("nav button").forEach(b=>b.classList.toggle("active",b.dataset.tab===t));$("formView").classList.toggle("hidden",t!=="form");$("historyView").classList.toggle("hidden",t!=="history");if(t==="history")renderHistory()}
let logoPngCache=null;
async function getLogoPng(){if(logoPngCache)return logoPngCache;const svg=await fetch("logo-grafitec.svg?v=2").then(r=>{if(!r.ok)throw new Error("logo");return r.blob()});const url=URL.createObjectURL(svg);try{const img=await new Promise((resolve,reject)=>{const el=new Image();el.onload=()=>resolve(el);el.onerror=reject;el.src=url});const canvas=document.createElement("canvas");canvas.width=800;canvas.height=540;const ctx=canvas.getContext("2d");ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);logoPngCache=canvas.toDataURL("image/png");return logoPngCache}finally{URL.revokeObjectURL(url)}}
async function printPdf(){const c=data();if(!c.contactName&&!c.company)return notice("Primero escriba el nombre del cliente o empresa.",true);if(!window.jspdf?.jsPDF)return notice("No se pudo cargar el generador de PDF. Revise su conexión e inténtelo nuevamente.",true);const btn=$("pdfBtn"),oldText=btn.textContent;btn.disabled=true;btn.textContent="Generando PDF…";try{const{jsPDF}=window.jspdf,doc=new jsPDF({orientation:"portrait",unit:"mm",format:"a4"});const left=12,right=198,blue=[36,84,134],black=[20,32,43];doc.setTextColor(...black);doc.setFont("helvetica","bold");doc.setFontSize(17);doc.text("CONTRATO",left,16);doc.text(String(c.contractNumber||""),right,16,{align:"right"});try{doc.addImage(await getLogoPng(),"PNG",left,23,40,27)}catch(e){console.warn("No se pudo cargar el logo",e)}doc.setFontSize(10);doc.setFont("helvetica","bold");doc.text("GRAFITEC WORLD PERÚ",58,27);doc.setFontSize(8.2);doc.setFont("helvetica","normal");const companyLines=["DE: Grafitec World Perú S.A.C.","RUC: 20616457561","Dirección Fiscal: Av. República de Argentina N.° 778, Int. 1066, Urb. Lima","Industrial - Lima - Lima","Cel.: 920102240"];companyLines.forEach((t,i)=>doc.text(t,58,33+i*3.5));const label=(name,value,x,y,w=64)=>{doc.setFont("helvetica","bold");doc.text(name,x,y);doc.setFont("helvetica","normal");doc.text(String(value||""),x+17,y,{maxWidth:w})};label("Sres.:",c.contactName,left,60,72);label("Fecha:",new Date(c.contractDate+"T12:00:00").toLocaleDateString("es-PE"),112,60,68);label("Empresa:",c.company,left,66,72);label("RUC:",c.taxId,left,72,72);label("Cel.:",c.phone,left,78,72);const body=c.items.map(it=>[it.quantity||"",it.unit||"",it.description||"",money(it.unitPrice),money(Number(it.quantity||0)*Number(it.unitPrice||0))]);while(body.length<10)body.push(["","","","",""]);doc.autoTable({startY:84,margin:{left,right:12},head:[["CANT.","UNIDAD","DESCRIPCIÓN","P. UNIT.","TOTAL"]],body,theme:"grid",styles:{font:"helvetica",fontSize:8,textColor:black,lineColor:[17,17,17],lineWidth:.25,cellPadding:1.5,minCellHeight:6},headStyles:{fillColor:blue,textColor:[255,255,255],fontStyle:"bold",halign:"center"},columnStyles:{0:{cellWidth:18,halign:"center"},1:{cellWidth:24,halign:"center"},2:{cellWidth:80},3:{cellWidth:28,halign:"right"},4:{cellWidth:36,halign:"right"}}});let y=doc.lastAutoTable.finalY;const totalX=136,totalW=62,rowH=7;[["TOTAL",money(c.total)],["A CUENTA",money(c.deposit)],["SALDO",money(c.balance)]].forEach((r,i)=>{doc.rect(totalX,y+i*rowH,totalW,rowH);doc.setFont("helvetica","bold");doc.text(r[0],totalX+2,y+4.8+i*rowH);doc.setFont("helvetica","normal");doc.text(r[1],totalX+totalW-2,y+4.8+i*rowH,{align:"right"})});let contentY=y+rowH*3+6;if(c.showConditions&&c.conditions){doc.setFontSize(8.5);doc.setFont("helvetica","bold");doc.text("Condiciones:",left,contentY);doc.setFont("helvetica","normal");const cond=c.conditions.split("\n").filter(Boolean);cond.forEach(t=>{contentY+=4;const lines=doc.splitTextToSize("• "+t,115);if(contentY+lines.length*3.6>268){doc.addPage();contentY=16}doc.text(lines,left,contentY);contentY+=(lines.length-1)*3.6})}if(contentY>242)doc.addPage();const by=267;doc.setFontSize(8.5);doc.setFont("helvetica","bold");doc.text("Cta. Corriente BBVA Soles: 0011-0348-0200504928",left,by);doc.text("CCI: 011-348-000200504928-09",left,by+4);doc.text("Grafitec World Perú S.A.C.",left,by+8);try{doc.addImage(PLIN_QR_DATA,"PNG",168,244,28,35)}catch(e){console.warn("No se pudo agregar el QR de Plin",e)};const clientFile=(c.contactName||c.company||"cliente").trim().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-zA-Z0-9 _-]/g,"").replace(/\s+/g,"_");doc.save(`contrato_${clientFile}.pdf`);notice(`PDF descargado como contrato_${clientFile}.pdf`)}catch(e){console.error(e);notice("No se pudo generar el PDF. Actualice la página e inténtelo nuevamente.",true)}finally{btn.disabled=false;btn.textContent=oldText}}
$("newBtn").onclick=fresh;$("addItem").onclick=()=>{items.push({quantity:"",unit:"Millares",description:"",unitPrice:""});renderItems()};$("saveBtn").onclick=save;$("pdfBtn").onclick=printPdf;$("deposit").oninput=calc;$("contractNumber").oninput=calc;$("showConditions").onchange=e=>$("conditionsWrap").classList.toggle("hidden",!e.target.checked);$("search").oninput=renderHistory;document.querySelector("nav").onclick=e=>e.target.closest("button[data-tab]")&&switchTab(e.target.closest("button").dataset.tab);$("items").oninput=e=>{const t=e.target;if(t.dataset.i!==undefined){items[Number(t.dataset.i)][t.dataset.f]=t.value;calc();if(t.dataset.f==="quantity"||t.dataset.f==="unitPrice"){const subtotal=t.closest(".item").querySelector(".subtotal b");subtotal.textContent=money(Number(items[Number(t.dataset.i)].quantity||0)*Number(items[Number(t.dataset.i)].unitPrice||0))}}};$("items").onchange=e=>{const t=e.target;if(t.dataset.i!==undefined){items[Number(t.dataset.i)][t.dataset.f]=t.value;calc()}};$("items").onclick=e=>{const b=e.target.closest("[data-remove]");if(b){items.splice(Number(b.dataset.remove),1);renderItems();calc()}};$("history").onclick=e=>{const b=e.target.closest("[data-open]");if(b)openContract(getAll().find(c=>c.id===Number(b.dataset.open)))};
$("exportBtn").onclick=()=>{const blob=new Blob([JSON.stringify(getAll(),null,2)],{type:"application/json"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=`respaldo-contratos-grafitex-${today()}.json`;a.click();URL.revokeObjectURL(a.href)};$("importFile").onchange=async e=>{try{const d=JSON.parse(await e.target.files[0].text());if(!Array.isArray(d))throw 0;setAll(d);renderHistory();notice("Respaldo importado correctamente.")}catch{notice("El archivo de respaldo no es válido.",true)}};fresh();renderHistory();
